  ('timelines', 'timelines', 'Term and timelines', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"This agreement starts on {{deal.start_date}}{{#if deal.end_date}} and ends on {{deal.end_date}}{{else}} and continues until terminated under this agreement{{/if}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Due dates for concepts, drafts and publication are set in the brief. The Creator will tell Eduwit through the Portal as soon as a due date is at risk."}]}]}'::jsonb, true, true, false, '{}'::text[]),
