  ('termination', 'termination', 'Termination', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"Either party may end this agreement by giving 15 days'' written notice through the Portal. Either party may end it immediately if the other materially breaches it and does not remedy the breach within 7 days of notice."}]},{"type":"paragraph","content":[{"type":"text","text":"On termination, amounts earned up to the termination date remain payable, subject to the Penalties clause, and commission on leads attributed before termination is paid as it is confirmed. The Disclosure, Claims, Confidentiality and Data protection clauses survive termination."}]}]}'::jsonb, true, true, false, '{}'::text[]),
  ('force_majeure', 'force_majeure', 'Force majeure', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"Neither party is liable for delay or failure caused by events beyond its reasonable control, including natural disasters, epidemics, government action or platform outages, provided it informs the other promptly and resumes performance as soon as reasonably possible. Due dates move by the length of the delay."}]}]}'::jsonb, false, false, false, '{}'::text[]),
  ('indemnity', 'indemnity', 'Indemnity and limitation of liability', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"Each party will indemnify the other against third-party claims arising from its breach of this agreement or its violation of law. Except for breaches of the Confidentiality and Data protection clauses and amounts payable under the Compensation clause, neither party is liable for indirect or consequential loss, and each party''s total liability is limited to the fees paid or payable under this agreement in the preceding twelve months."}]}]}'::jsonb, false, true, false, '{}'::text[]),
  ('disputes', 'disputes', 'Dispute resolution and jurisdiction', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"The parties will first try to resolve any dispute through good-faith discussion for 30 days. Unresolved disputes are referred to arbitration by a sole arbitrator under the Arbitration and Conciliation Act, 1996, seated in Ghaziabad, Uttar Pradesh, in English. This agreement is governed by the laws of India, and subject to arbitration the courts at Ghaziabad have exclusive jurisdiction."}]}]}'::jsonb, true, false, false, '{}'::text[]),
  ('notices', 'notices', 'Notices', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"Notices under this agreement are given through the Portal or by email: to Eduwit at {{eduwit.support_email}}, and to the Creator at {{creator.email}}. A notice is received when it is shown in the Portal or one business day after the email is sent."}]}]}'::jsonb, false, false, false, '{}'::text[]),
  ('entire_agreement', 'entire_agreement', 'Entire agreement and signatures', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"This agreement, the accepted terms of the Deal and the briefs issued under it form the entire agreement between the parties on its subject. {{#if contract.is_amendment}}This agreement amends contract {{contract.parent_number}}; the rest of that contract continues to apply.{{/if}} Changes are valid only as a new version of this agreement signed through the Portal."}]},{"type":"paragraph","content":[{"type":"text","text":"The parties agree to sign electronically. Each signature is verified with a one-time code and recorded with the document''s SHA-256 hash, which is printed on the signature certificate."}]}]}'::jsonb, true, false, true, '{}'::text[]);
insert into inf.clauses (key, category, deal_types) select key, category, deal_types from _seed on conflict (key) do nothing;
insert into inf.clause_versions (clause_id, version, title, body, required, negotiable, locked)
select c.id, 1, s.title, s.body, s.required, s.negotiable, s.locked from _seed s join inf.clauses c on c.key = s.key
on conflict (clause_id, version) do nothing;

insert into inf.contract_templates (key, name, description, title, header, footer, is_default)
select 'standard_creator_agreement', 'Standard creator agreement', 'Adapts to every deal type through conditional clauses. All clauses are drafts until legally reviewed.', 'Creator Agreement {{contract.number}}',
       '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DRAFT — requires legal review before use."}]},{"type":"paragraph","content":[{"type":"text","text":"Contract {{contract.number}} dated {{contract.date}}, for deal {{deal.code}}."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Signed electronically for {{eduwit.legal_name}} by {{eduwit.signatory_name}}, {{eduwit.signatory_designation}}, and by {{creator.legal_name}}. The signature certificate follows."}]}]}'::jsonb,
       not exists (select 1 from inf.contract_templates where is_default and archived_at is null)
where not exists (select 1 from inf.contract_templates where key = 'standard_creator_agreement');
